class Solution {
public:
    int waysToPartition(vector<int>& nums, int k) {
        int n = nums.size();
        long long total = 0;
        for (int x : nums) total += x;
        vector<long long> pref(n);
        pref[0] = nums[0];
        for (int i = 1; i < n; ++i) pref[i] = pref[i - 1] + nums[i];
        vector<long long> diffs(n - 1);
        unordered_map<long long, int> right_count, left_count;
        for (int i = 0; i < n - 1; ++i) {
            diffs[i] = 2 * pref[i] - total;
            right_count[diffs[i]]++;
        }
        int ans = right_count[0];
        for (int i = 0; i < n; ++i) {
            long long d = (long long)k - nums[i];
            int curr = left_count[d] + right_count[-d];
            ans = max(ans, curr);
            if (i < n - 1) {
                long long diff = diffs[i];
                right_count[diff]--;
                left_count[diff]++;
            }
        }
        return ans;
    }
};

class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        long total = 0;
        for (int x : nums) total += x;
        long[] pref = new long[n];
        pref[0] = nums[0];
        for (int i = 1; i < n; i++) pref[i] = pref[i - 1] + nums[i];

        long[] diffs = new long[n - 1];
        Map<Long, Integer> rightCount = new HashMap<>();
        Map<Long, Integer> leftCount = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            diffs[i] = 2 * pref[i] - total;
            rightCount.put(diffs[i], rightCount.getOrDefault(diffs[i], 0) + 1);
        }
        int ans = rightCount.getOrDefault(0L, 0);
        for (int i = 0; i < n; i++) {
            long d = (long)k - nums[i];
            int curr = leftCount.getOrDefault(d, 0) + rightCount.getOrDefault(-d, 0);
            ans = Math.max(ans, curr);
            if (i < n - 1) {
                long diff = diffs[i];
                rightCount.put(diff, rightCount.get(diff) - 1);
                leftCount.put(diff, leftCount.getOrDefault(diff, 0) + 1);
            }
        }
        return ans;
    }
}

var waysToPartition = function(nums, k) {
