  for (let i = 0; i < n - 1; i++) {
    diffs[i] = 2 * pref[i] - total;
    rightCount.set(diffs[i], (rightCount.get(diffs[i]) || 0) + 1);
  }
  let ans = rightCount.get(0) || 0;
  for (let i = 0; i < n; i++) {
    const d = k - nums[i];
    const curr = (leftCount.get(d) || 0) + (rightCount.get(-d) || 0);
    ans = Math.max(ans, curr);
    if (i < n - 1) {
      const diff = diffs[i];
      rightCount.set(diff, rightCount.get(diff) - 1);
